select exists(select 1 from information_schema.columns where table_schema='public' and table_name='cool_spots' and column_name='hours_time_zone') as ready \gset
\if :ready
insert into places(id,name,location) values ('00000000-0000-4000-8000-000000000401','Cooling Test','SRID=4326;POINT(0 51)');
insert into cool_spots(id,place_id) values ('db-cooling-content','00000000-0000-4000-8000-000000000401');
select results_eq($$select setting,cost,eligibility,seating,drinking_water,toilets,wheelchair_access,staffed_when_open,tables,posted_stay_limit_status from cool_spots where id='db-cooling-content'$$,
 $$values ('unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text,'unknown'::text)$$, 'missing facts stay unknown rather than becoming no/free/everyone');
select ok((select cooling_features='{}'::text[] and cooling_details is null and area_description is null and additional_information is null and posted_stay_limit_minutes is null and hours_text is null and hours_time_zone is null from cool_spots where id='db-cooling-content'), 'optional information remains absent');
select lives_ok($$update cool_spots set setting='indoors' where id='db-cooling-content'$$, 'DB-C31: accepts setting indoors');
select lives_ok($$update cool_spots set setting='outdoors' where id='db-cooling-content'$$, 'DB-C31: accepts setting outdoors');
