select lives_ok($$update cool_spots set cooling_details=E'  四樓 reading room\n' where id='db-cooling-content'$$,'DB-C32: preserves meaningful cooling_details');
select is((select cooling_details from cool_spots where id='db-cooling-content'), E'  四樓 reading room\n', 'reads original cooling_details');
