select lives_ok($$update cool_spots set area_description=E'  四樓 reading room\n' where id='db-cooling-content'$$,'DB-C32: preserves meaningful area_description');
select is((select area_description from cool_spots where id='db-cooling-content'), E'  四樓 reading room\n', 'reads original area_description');
select throws_ok($$update cool_spots set area_description='' where id='db-cooling-content'$$,'23514',null,'rejects blank area_description');
select throws_ok($$update cool_spots set area_description=U&'\0020\0009\3000' where id='db-cooling-content'$$,'23514',null,'rejects blank area_description');
select lives_ok($$update cool_spots set area_description=null where id='db-cooling-content'$$,'allows clearing optional area_description');
