select throws_ok($$update cool_spots set posted_stay_limit_status='invalid',posted_stay_limit_minutes=null where id='db-cooling-content'$$,'23514',null,'DB-C33: invalid with null minutes');
select throws_ok($$update cool_spots set hours_text='Monday 9-5' where id='db-cooling-content'$$,'23514',null,'requires a time zone alongside hours');
select lives_ok($$update cool_spots set hours_text='Monday 9-5',hours_time_zone='Europe/London' where id='db-cooling-content'$$,'preserves supplied hours without inferring open now');
select throws_ok($$update cool_spots set hours_time_zone='' where id='db-cooling-content'$$,'23514',null,'rejects an empty hours time zone');
select lives_ok($$update cool_spots set hours_text=null,hours_time_zone=null where id='db-cooling-content'$$,'allows unknown hours');
select ok((select place_id='00000000-0000-4000-8000-000000000401' from cool_spots where id='db-cooling-content'),'content updates preserve both identities');
\else
select skip('behavior requires the new cooling-content columns');
\endif
select * from finish();
rollback;
